Section FPER.
Variables (st0 st : mstate) (m : mem).
Hypothesis MR : rmrep st m.
Hypothesis ER : ENTRY_REL st0 st.

Lemma rst0_region rid r : (s_regions st0) !! rid = Some r ->
  0 <= r_base r /\ r_base r + round_up_pg (r_len r) <= ATOP
  /\ (r_base r + round_up_pg (r_len r) <= 0x10000 \/ 0x12000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x12000 \/ 0x2a000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x2a000 \/ 0x2b000 <= r_base r)
  /\ (r_base r + round_up_pg (r_len r) <= 0x2b000 \/ 0x5d000 <= r_base r).
Proof.
